"""Writes docs/COMPILATION-CHECK.md from data/analysis/compilation-verification.json and data/compilation-corrections.json: which curves taken from the SWIFT/VELOCIraptor compilation were checked against their original papers, what was found, and what was done about it. Generated; do not edit by hand.
Usage: python3 scripts/make-compilation-check-doc.py"""
import json
from collections import Counter
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
V = json.loads((ROOT / "data" / "analysis" / "compilation-verification.json").read_text())
C = json.loads((ROOT / "data" / "compilation-corrections.json").read_text())["corrections"]
cmap = {c["id"]: c for c in C}
LABEL = {"agrees": "agrees", "fit-only": "agrees with the paper's fit", "disagrees": "**disagrees**", "not-verifiable": "cannot be checked"}


def summary():
    n = Counter()
    for row in V["curves"]:
        n[row["result"]] += len(row["records"])
    return n


def main():
    n = summary()
    total = sum(n.values())
    changed = {r for c in C if c.get("kind") in ("numeric", "label") for r in c["records"]}
    numeric = {r for c in C if c.get("kind") == "numeric" for r in c["records"]}
    flagged = {r for c in C if c.get("kind") == "flag" for r in c["records"]}
    L = ["# Observation curves from the compilation, checked against their papers", "",
         "*Generated by `scripts/make-compilation-check-doc.py` from `data/analysis/compilation-verification.json` and `data/compilation-corrections.json`; do not edit by hand.*", "",
         "173 observation curves come from the SWIFT/VELOCIraptor comparison-data compilation, whose scripts re-express each published table in their own conventions (h, IMF, units). Nobody had checked those conversions against the original papers. For the curves below, a reader went to the paper itself (its arXiv source or PDF) and to the compilation's script and raw file, and compared the stored curve with the paper's printed numbers or figure after the paper's own h and IMF.", "",
         f"**{total} records were checked. {n['agrees']} agree, {n['fit-only']} agree with the fit the paper prints, {n['disagrees']} disagree and {n['not-verifiable']} cannot be checked** because the paper does not contain the numbers. The rest of the 173 have not been checked.", "",
         f"What was done: {len(numeric)} records had their numbers shifted, by a stated amount, because the compilation's conversion was wrong ({', '.join(sorted({c['id'] for c in C if c.get('kind') == 'numeric'}))}); {len(changed - numeric)} further records had a label corrected (cosmology, population, velocity or mass definition, tier, or rankability) so that the record says what the numbers are; {len(flagged)} records carry a note on something the paper does not support, with the numbers left alone. Every change is in `data/compilation-corrections.json` with its evidence, is written into the record's warning, can be undone (the hash of the original points is kept), and is re-checked by `scripts/test-compilation-corrections.mjs`.", "",
         "Limits: the checks were made by one reader working from the papers and the compilation's scripts. No author, no maintainer of the compilation and no outside expert has reviewed them. 'Agrees' means within 0.02 dex of the paper's printed numbers after the paper's own conversion; it does not mean the paper's own measurement is right. Where a conversion depends on a choice the paper does not state (an IMF, a solar metallicity), the note says so and the numbers are left as they were.", "",
         "| records | paper (arXiv) | result | size of the difference | cause | what we did |", "|---|---|---|---|---|---|"]
    for row in V["curves"]:
        recs = ", ".join(f"`{r.replace('vcd.', '')}`" for r in row["records"])
        did = ", ".join(f"`{i}` ({cmap[i]['kind']})" for i in row["corrections"]) or "nothing needed"
        L.append(f"| {recs} | {row['paper'] or 'n/a'} | {LABEL[row['result']]} | {row['size']} | {row['cause']} | {did} |")
    mm = json.loads((ROOT / "data" / "analysis" / "compilation-metadata-mismatches.json").read_text())
    L += ["", "## Records whose own citation names another paper", "", mm["about"], "", "| record | citation here | citation carried by the compilation |", "|---|---|---|"]
    L += [f"| `{m['recordId'].replace('vcd.', '')}` | {m['citation']} | {m['upstreamCitation']} |" for m in mm["records"]]
    L += ["", "## What should be told to the compilation's maintainers", "",
          "`docs/UPSTREAM-ISSUES.md` holds drafts, not sent, for the errors that are in their scripts (Grazian 2015 treats h_70 units as h-free; Gonzalez 2011 omits the Salpeter conversion its comment claims; the Avila-Reese 2008 mass transform and its source; unconverted h in several scripts).", ""]
    (ROOT / "docs" / "COMPILATION-CHECK.md").write_text("\n".join(L))
    print(f"wrote docs/COMPILATION-CHECK.md: {total} records, {n['disagrees']} disagree")


if __name__ == "__main__":
    main()
